// Real frames captured from the Java emitter (MusicPlayerView, Spring SSR path):
// the COMPACT mount, and the HSTACK-wrapper fit cycles (compact→wide→narrow→wide).
const MOUNT = hex(read("mount.hex"));
const WIDE = hex(read("swap-wide.hex"));
const NARROW = hex(read("swap-narrow.hex"));
const WIDE2 = hex(read("swap-wide2.hex"));

function read(name: string): string {
  const here = dirname(fileURLToPath(import.meta.url));
  return readFileSync(resolve(here, "fixtures/fit", name), "utf8").trim();
}

function hex(h: string): Uint8Array {
  const out = new Uint8Array(h.length / 2);
  for (let i = 0; i < out.length; i++) out[i] = parseInt(h.slice(i * 2, i * 2 + 2), 16);
  return out;
}

function attachCompact(r: DomRenderer): HTMLElement {
  document.body.innerHTML = "";
  applyBatch(parseBatch(MOUNT), r);
  const root = r.byId.get(1) as HTMLElement;
  expect(root).toBeTruthy();
  document.body.appendChild(root);
  return root;
}

/** The fit row (the slot's only child) and, for a sidebar, its text. */
function rowOf(root: HTMLElement): HTMLElement {
  return root.children[0] as HTMLElement;
}

function directChildTexts(row: HTMLElement): string[] {
  return Array.from(row.children).map((c) => (c as HTMLElement).textContent ?? "");
}

function rowSidebarCount(row: HTMLElement): number {
  return Array.from(row.children).filter((c) => (c.textContent ?? "").includes("Now Playing")).length;
}

describe("SizeThatFits swap replay (real MusicPlayerView frames)", () => {
  it("wide swap appends the sidebar AFTER the main area (trailing, right)", () => {
    const r: DomRenderer = { byId: new Map() };
    const root = attachCompact(r);

    expect(() => applyBatch(parseBatch(WIDE), r)).not.toThrow();

    const row = rowOf(root);
    const texts = directChildTexts(row);
    const libraryIdx = texts.findIndex((t) => t.includes("Library"));
    const nowPlayingIdx = texts.findIndex((t) => t.includes("Now Playing"));
    expect(libraryIdx).toBeGreaterThanOrEqual(0);
    expect(nowPlayingIdx).toBeGreaterThan(libraryIdx),
      `sidebar must come AFTER the main area; row order was: ${JSON.stringify(texts.map((t) => t.slice(0, 24)))}`;
  });

  it("narrow->wide cycles leave exactly ONE sidebar and keep it trailing", () => {
    const r: DomRenderer = { byId: new Map() };
    const root = attachCompact(r);

    applyBatch(parseBatch(WIDE), r);
    applyBatch(parseBatch(NARROW), r);
    applyBatch(parseBatch(WIDE2), r);

    const row = rowOf(root);
    expect(rowSidebarCount(row)).toBe(1),
      "no duplicate now-playing bar after a full wide->narrow->wide cycle";
    const texts = directChildTexts(row);
    const lib = texts.findIndex((t) => t.includes("Library"));
    const np = texts.findIndex((t) => t.includes("Now Playing"));
    expect(lib).toBeGreaterThanOrEqual(0);
    expect(np).toBeGreaterThan(lib), `sidebar stays trailing: ${JSON.stringify(texts)}`;
  });

  it("debug-comment siblings do not move the sidebar to the LEFT", () => {
    // pathland.debug-html=true (Spring demo) prefixes every element with its
    // `<!-- #N … -->` comment as a sibling CHILD of the container. The INSERT
    // index counts ELEMENT children, so `insertAt` must ignore the comment
    // nodes — otherwise a trailing insert lands BEFORE the main area.
    const r: DomRenderer = { byId: new Map() };
    const root = attachCompact(r);
    const row = rowOf(root);
    const main = row.children[0] as HTMLElement;
    row.insertBefore(document.createComment("#3 ZStack: alignment=4"), main);

    expect(() => applyBatch(parseBatch(WIDE), r)).not.toThrow();

    const texts = directChildTexts(row);
    const libraryIdx = texts.findIndex((t) => t.includes("Library"));
    const nowPlayingIdx = texts.findIndex((t) => t.includes("Now Playing"));
    expect(libraryIdx).toBeGreaterThanOrEqual(0);
    expect(nowPlayingIdx).toBeGreaterThan(libraryIdx),
      `sidebar must still be trailing despite the debug comment; row order: ${JSON.stringify(texts.map((t) => t.slice(0, 24)))}`;
  });
});

/** Create the DOM shell for a node of {@code component}. Returns a Node (elements or an inert comment). */
export function createElement(component: number): Node {
  switch (component) {
    case COMPONENT_VSTACK:
    case COMPONENT_LAZY_VSTACK:
      return flexBox("column");
    case COMPONENT_HSTACK:
    case COMPONENT_LAZY_HSTACK:
      return flexBox("row");
    case COMPONENT_ZSTACK: {
      // ZStack (SwiftUI ZStack / Compose Box): an overlapping grid — children
      // share one cell (`grid-area:1/1`) and are positioned per ALIGNMENT
      // (mirrors the Rust SSR renderer). The container's size (hug-to-largest-
      // child / Fixed / FILL / fill-propagation) is resolved by the layout pass.
      const el = document.createElement("div");
      el.style.display = "grid";
      el.style.isolation = "isolate";
      el.style.gridTemplateColumns = "minmax(0,1fr)";
      el.style.gridTemplateRows = "minmax(0,1fr)";
      // Position children on both axes per the ZSTACK ALIGNMENT (default start).
      el.style.justifyItems = "start";
      el.style.alignItems = "start";
      return el;
    }
    case COMPONENT_GRID:
    case COMPONENT_LAZY_VGRID:
    case COMPONENT_LAZY_HGRID: {
      const el = document.createElement("div");
      el.style.display = "grid";
      // Cells keep their size and position within their tracks (spec §grid
      // model); `justify-items`/`align-items` come from the grid ALIGNMENT.
      el.style.justifyItems = "start";
      el.style.alignItems = "start";
      // Lazy horizontal grids flow into auto columns (mirrors the Rust SSR
      // renderer's `grid-auto-flow:column;grid-auto-columns:1fr`).
      if (component === COMPONENT_LAZY_HGRID) {
        el.style.gridAutoFlow = "column";
        el.style.gridAutoColumns = "minmax(0,1fr)";
      }
      return el;
    }
    case COMPONENT_GRID_ROW: {
      // A grid's explicit row grouping (spec §GridRow): transparent
      // (`display:contents`) — its cell children participate in the parent
      // GRID's layout (mirrors the Rust SSR renderer). Renders nothing outside
      // a GRID.
      const el = document.createElement("div");
      el.style.display = "contents";
      return el;
    }
    case COMPONENT_SCROLLVIEW: {
      const el = document.createElement("div");
