/**
 * The player bar's control surface: a centered row of
 * `[rewind] [play-pause] [forward] | [cover art] [track title] | [volume]`
 * over a slim, draggable seek bar that reports progress as a percent.
 */
internal class PlayerControls(
    private val player: MediaController,
    private val trackIndex: WritableSignal<Int>,
) : KotlinView() {

    override fun body(): View {
        val current = computed { MusicPlayerView.at(trackIndex.get()) }
        val transportIcon = computed {
            if (player.playing().get()) IconName.PAUSE.wire() else IconName.PLAY.wire()
        }
        val seek = SeekControl(player.time(), player.position())
        val volumeControl = VolumeControl(player.volumeReport(), player.volume())

        val playControl = HStack(alignment = VerticalAlignment.CENTER, spacing = 18f) {
            Button(action = { prev() }) {
                Icon(IconName.SKIP_BACK)
            }.fontSize(20f)
                .accessibilityLabel("Previous track")

            Button(action = { player.toggle() }) {
                Icon(transportIcon)
            }.fontSize(20f)
                .accessibilityLabel(computed { if (player.playing().get()) "Pause" else "Play" })

            Button(action = { next() }) {
                Icon(IconName.SKIP_FORWARD)
            }.fontSize(20f)
                .accessibilityLabel("Next track")
        }

        val trackInfo = HStack(alignment = VerticalAlignment.CENTER, spacing = 18f) {
            Image(computed { current.get().cover })
                .frame(width = 36f, height = 36f)
                .scaledToFit()

            VStack(alignment = HorizontalAlignment.LEADING, spacing = 2f) {
                Text(computed { current.get().title })
                    .fontWeight(FontWeight.SEMIBOLD)
                    .lineLimit(1)
                Text(computed { current.get().artist })
                    .fontSize(13f)
                    .foregroundStyle(MusicPlayerView.SECONDARY_FG)
                    .lineLimit(1)
            }.frame(width = 160f)
        }

        val volumeView = HStack(alignment = VerticalAlignment.CENTER, spacing = 18f) {
            Icon(IconName.VOLUME).fontSize(16f)
            Slider(volumeControl, 0f..1f)
                .accessibilityLabel("Volume")
        }

        val compactControls = HStack(alignment = VerticalAlignment.CENTER, spacing = 18f) {
            +playControl
            Text("|").fontSize(18f).foregroundStyle(MusicPlayerView.SECONDARY_FG)
            +trackInfo
        }

        val controls = HStack(alignment = VerticalAlignment.CENTER, spacing = 18f) {
            +playControl
            Text("|").fontSize(18f).foregroundStyle(MusicPlayerView.SECONDARY_FG)
            +trackInfo
            Text("|").fontSize(18f).foregroundStyle(MusicPlayerView.SECONDARY_FG)
            +volumeView
        }

        val groups = ViewThatFits(
            Fit(controls, 700f),
            Fit(compactControls),
        )

        return VStack(alignment = HorizontalAlignment.CENTER, spacing = 0f) {
            +groups
            Slider(
                PercentSeek(seek) { MusicPlayerView.at(trackIndex.get()).duration },
                0f..100f,
                seek::onEditingChanged,
            ).frame { width(Float.POSITIVE_INFINITY) }
                .padding(top = 0f, right = 16f, bottom = 0f, left = 16f)
                .accessibilityLabel("Seek")
        }
    }

    /** Previous track (wraps around), restarting from the top. */
    private fun prev() {
        trackIndex.set((trackIndex.get() - 1 + MusicPlayerView.TRACKS.size) % MusicPlayerView.TRACKS.size)
        player.seek(0f)
    }

    /** Next track (wraps around), restarting from the top. */
    private fun next() {
        trackIndex.set((trackIndex.get() + 1) % MusicPlayerView.TRACKS.size)
        player.seek(0f)
    }
}

package dev.pathland.view.dsl

import dev.pathland.view.core.Modified
import dev.pathland.view.core.PathlandDsl
import dev.pathland.view.core.View
import java.util.ArrayDeque

/**
 * The receiver for view-builder blocks. It carries no members of its own; its
 * purpose is to give nested view builders an annotated receiver so an outer
 * DSL receiver (a router or modifier config) cannot be captured implicitly.
 *
 * The builder is synchronous and single-threaded (the same contract as the
 * emitter and the environment), so a thread-local child stack is still the
 * equivalent of SwiftUI's result builder.
 */
@PathlandDsl
object PathlandScope

internal object ViewScopes {
    private val stack = ThreadLocal.withInitial { ArrayDeque<MutableList<View>>() }

    fun push(): MutableList<View> {
        val scope = mutableListOf<View>()
        stack.get().addLast(scope)
        return scope
    }

    fun pop() {
        stack.get().removeLast()
    }

    fun current(): MutableList<View>? = stack.get().peekLast()

    fun register(view: View) {
        val scope = current() ?: return
        // A DSL leaf/container registers its base view as soon as it is constructed.
        // A following modifier chain then registers the wrapper; replace the base in
        // place so `.padding(16)` on a child is not silently dropped.
        val inner = (view as? Modified)?.inner()
        if (inner != null) {
            val index = scope.indexOfFirst { it === inner }
            if (index >= 0) {
                scope[index] = view
                return
            }
        }
        if (scope.none { it === view }) {
            scope.add(view)
        }
    }

    fun unregister(view: View) {
        current()?.removeAll { it === view }
    }
}

/**
 * Add a view built outside the DSL builders (e.g. a non-DSL `View` or a
 * pre-constructed component) to the current block.
 */
fun View.add(): View = registerChild()

/** Prefix form: `+prebuiltView`. */
operator fun View.unaryPlus(): View = registerChild()

/**
 * Collect the views declared by [content]. A newly declared child auto-registers
 * into the innermost active scope, so `VStack { Text("a"); Text("b") }` needs no
 * `.children(...)` boilerplate.
 */
fun collectChildren(content: PathlandScope.() -> Unit): List<View> {
    val scope = ViewScopes.push()
    return try {
        PathlandScope.content()
        scope.toList()
    } finally {
        ViewScopes.pop()
    }
}

internal fun <T : View> T.registerChild(): T {
    ViewScopes.register(this)
    return this
}

/** Collect a ForEach row into one child view (a single child stays unwrapped). */
internal fun rowView(content: PathlandScope.() -> Unit): View {
    val children = collectChildren(content)
    return when (children.size) {
        0 -> groupView(emptyList())
        1 -> children[0]
        else -> groupView(children)
    }
}

